create table if not exists private.player_immortal_states(user_id uuid not null references auth.users(id)on delete cascade,channel text not null check(channel in('formal','test')),residual_source bigint not null default 0 check(residual_source>=0),barren_traces bigint not null default 0 check(barren_traces>=0),timeline_started_at timestamptz not null default now(),region text not null default'ascension-platform'check(region in('ascension-platform','wuxi-wasteland')),investigated jsonb not null default'[]'check(jsonb_typeof(investigated)='array'),first_battle_won boolean not null default false,guide_stone_stage integer not null default 0 check(guide_stone_stage between 0 and 3),expedition_unlocked boolean not null default false,expedition_active boolean not null default false,expedition_node integer not null default 0 check(expedition_node between 0 and 4),expedition_runs integer not null default 0 check(expedition_runs>=0),outer_route_cleared boolean not null default false,expedition_day date,expedition_used integer not null default 0 check(expedition_used between 0 and 3),story_flags jsonb not null default'{}'check(jsonb_typeof(story_flags)='object'),platform_chapter_completed boolean not null default false,wasteland_arrival_seen boolean not null default false,wasteland_selected_route text not null default'dryWind'check(wasteland_selected_route in('dryWind','sunken','kneeling')),wasteland_route_progress jsonb not null default'{"dryWind":0,"sunken":0,"kneeling":0}'check(jsonb_typeof(wasteland_route_progress)='object'),wasteland_outpost_stage integer not null default 0 check(wasteland_outpost_stage between 0 and 3),wasteland_body_stage integer not null default 0 check(wasteland_body_stage between 0 and 3),wasteland_story_flags jsonb not null default'{}'check(jsonb_typeof(wasteland_story_flags)='object'),imported boolean not null default false,revision bigint not null default 1,updated_at timestamptz not null default now(),primary key(user_id,channel));
alter table private.player_immortal_states enable row level security;revoke all on private.player_immortal_states from public,anon,authenticated;
create table if not exists private.legacy_immortal_import_eligibility(user_id uuid primary key references auth.users(id)on delete cascade,granted_at timestamptz not null default now());insert into private.legacy_immortal_import_eligibility(user_id)select id from auth.users on conflict do nothing;alter table private.legacy_immortal_import_eligibility enable row level security;revoke all on private.legacy_immortal_import_eligibility from public,anon,authenticated;
create or replace function private.immortal_day()returns date language sql stable set search_path='' as $$select(now()at time zone'Asia/Taipei')::date$$;
create or replace function private.immortal_snapshot(s private.player_immortal_states)returns jsonb language sql stable set search_path='' as $$select jsonb_build_object('revision',s.revision,'residualSource',s.residual_source,'barrenTraces',s.barren_traces,'timelineStartedAt',floor(extract(epoch from s.timeline_started_at)*1000),'region',s.region,'investigated',s.investigated,'firstBattleWon',s.first_battle_won,'guideStoneStage',s.guide_stone_stage,'expeditionUnlocked',s.expedition_unlocked,'expedition',jsonb_build_object('active',s.expedition_active,'node',s.expedition_node,'runs',s.expedition_runs),'outerRouteCleared',s.outer_route_cleared,'expeditionDaily',jsonb_build_object('date',private.immortal_day()::text,'used',case when s.expedition_day=private.immortal_day()then s.expedition_used else 0 end),'storyFlags',s.story_flags,'platformChapterCompleted',s.platform_chapter_completed,'wasteland',jsonb_build_object('arrivalSeen',s.wasteland_arrival_seen,'selectedRoute',s.wasteland_selected_route,'routeProgress',s.wasteland_route_progress,'outpostStage',s.wasteland_outpost_stage,'bodyStage',s.wasteland_body_stage,'storyFlags',s.wasteland_story_flags))$$;

create or replace function public.player_immortal_bootstrap(p_channel text,p_legacy jsonb)returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=(select auth.uid());s private.player_immortal_states;eligible boolean;w jsonb;rp jsonb;inv jsonb;
begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test')then raise exception '版本不正確';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-immortal-'||p_channel));select exists(select 1 from private.legacy_immortal_import_eligibility where user_id=uid)into eligible;insert into private.player_immortal_states(user_id,channel)values(uid,p_channel)on conflict do nothing;select * into s from private.player_immortal_states where user_id=uid and channel=p_channel for update;
 if not s.imported then if eligible and jsonb_typeof(coalesce(p_legacy,'{}'))='object'then w:=coalesce(p_legacy->'wasteland','{}');inv:=case when jsonb_typeof(p_legacy->'investigated')='array'then p_legacy->'investigated'else'[]'::jsonb end;select coalesce(jsonb_agg(distinct value),'[]'::jsonb)into inv from jsonb_array_elements(inv)where value#>>'{}'in('array','stele','gate');rp:=jsonb_build_object('dryWind',least(3,greatest(0,coalesce((w->'routeProgress'->>'dryWind')::integer,0))),'sunken',least(3,greatest(0,coalesce((w->'routeProgress'->>'sunken')::integer,0))),'kneeling',least(3,greatest(0,coalesce((w->'routeProgress'->>'kneeling')::integer,0))));update private.player_immortal_states set residual_source=least(1000000000,greatest(0,coalesce((p_legacy->>'residualSource')::bigint,0))),barren_traces=least(1000000000,greatest(0,coalesce((p_legacy->>'barrenTraces')::bigint,0))),timeline_started_at=to_timestamp(coalesce((p_legacy->>'timelineStartedAt')::numeric,extract(epoch from now())*1000)/1000),region=case when p_legacy->>'region'='wuxi-wasteland'then'wuxi-wasteland'else'ascension-platform'end,investigated=inv,first_battle_won=coalesce((p_legacy->>'firstBattleWon')::boolean,false),guide_stone_stage=least(3,greatest(0,coalesce((p_legacy->>'guideStoneStage')::integer,0))),expedition_unlocked=coalesce((p_legacy->>'expeditionUnlocked')::boolean,false),expedition_active=coalesce((p_legacy->'expedition'->>'active')::boolean,false),expedition_node=least(4,greatest(0,coalesce((p_legacy->'expedition'->>'node')::integer,0))),expedition_runs=greatest(0,coalesce((p_legacy->'expedition'->>'runs')::integer,0)),outer_route_cleared=coalesce((p_legacy->>'outerRouteCleared')::boolean,false),expedition_day=case when p_legacy->'expeditionDaily'->>'date'~'^\d{4}-\d{2}-\d{2}$'then(p_legacy->'expeditionDaily'->>'date')::date else null end,expedition_used=least(3,greatest(0,coalesce((p_legacy->'expeditionDaily'->>'used')::integer,0))),story_flags=case when jsonb_typeof(p_legacy->'storyFlags')='object'then p_legacy->'storyFlags'else'{}'::jsonb end,platform_chapter_completed=coalesce((p_legacy->>'platformChapterCompleted')::boolean,false),wasteland_arrival_seen=coalesce((w->>'arrivalSeen')::boolean,false),wasteland_selected_route=case when w->>'selectedRoute'in('dryWind','sunken','kneeling')then w->>'selectedRoute'else'dryWind'end,wasteland_route_progress=rp,wasteland_outpost_stage=least(3,greatest(0,coalesce((w->>'outpostStage')::integer,0))),wasteland_body_stage=least(3,greatest(0,coalesce((w->>'bodyStage')::integer,0))),wasteland_story_flags=case when jsonb_typeof(w->'storyFlags')='object'then w->'storyFlags'else'{}'::jsonb end,imported=true,revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into s;else update private.player_immortal_states set imported=true where user_id=uid and channel=p_channel returning * into s;end if;end if;return private.immortal_snapshot(s);exception when invalid_text_representation or numeric_value_out_of_range then raise exception '仙界舊進度資料不正確';end$$;

create or replace function public.player_immortal_wasteland_route(p_channel text,p_route text,p_request_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=(select auth.uid());s private.player_immortal_states;a private.player_ascension_states;progress integer;gain_source integer;gain_trace integer;
begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test')or p_route not in('dryWind','sunken','kneeling')or p_request_id is null then raise exception '荒原遠征請求不正確';end if;if exists(select 1 from private.player_state_events where user_id=uid and channel=p_channel and request_id=p_request_id)then raise exception '重複的荒原遠征請求';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-immortal-'||p_channel));select * into s from private.player_immortal_states where user_id=uid and channel=p_channel for update;select * into a from private.player_ascension_states where user_id=uid and channel=p_channel;if s.user_id is null or not a.ascended then raise exception '尚未踏入仙界';end if;if s.guide_stone_stage<3 or not s.outer_route_cleared then raise exception '無息荒原尚未解鎖';end if;if p_route='sunken'and coalesce((s.wasteland_route_progress->>'dryWind')::integer,0)<3 or p_route='kneeling'and coalesce((s.wasteland_route_progress->>'sunken')::integer,0)<3 then raise exception '此荒原路線尚未發現';end if;if s.expedition_day is distinct from private.immortal_day()then s.expedition_day:=private.immortal_day();s.expedition_used:=0;end if;if s.expedition_used>=3 then raise exception '今日遠征次數已盡';end if;progress:=least(3,coalesce((s.wasteland_route_progress->>p_route)::integer,0)+1);gain_source:=case p_route when'dryWind'then 1 when'sunken'then 4 else 2 end;gain_trace:=case p_route when'dryWind'then 2 when'kneeling'then 1 else 0 end;update private.player_immortal_states set expedition_day=s.expedition_day,expedition_used=s.expedition_used+1,residual_source=residual_source+gain_source,barren_traces=barren_traces+gain_trace,wasteland_selected_route=p_route,wasteland_route_progress=jsonb_set(wasteland_route_progress,array[p_route],to_jsonb(progress),true),wasteland_story_flags=case when p_route='kneeling'and progress=1 then jsonb_set(wasteland_story_flags,'{kneelingAwoke}','true',true)else wasteland_story_flags end,revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into s;insert into private.player_state_events(user_id,channel,revision,event_type,request_id,payload)values(uid,p_channel,s.revision,'immortal_wasteland_route',p_request_id,jsonb_build_object('route',p_route,'progress',progress,'residualSource',gain_source,'barrenTraces',gain_trace));return private.immortal_snapshot(s);end$$;

create or replace function public.player_immortal_body_upgrade(p_channel text,p_request_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=(select auth.uid());s private.player_immortal_states;a private.player_ascension_states;source_cost integer[]:=array[4,8,14];trace_cost integer[]:=array[2,4,7];idx integer;
begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test')or p_request_id is null then raise exception '界軀升階請求不正確';end if;if exists(select 1 from private.player_state_events where user_id=uid and channel=p_channel and request_id=p_request_id)then raise exception '重複的界軀升階請求';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-immortal-'||p_channel));select * into s from private.player_immortal_states where user_id=uid and channel=p_channel for update;select * into a from private.player_ascension_states where user_id=uid and channel=p_channel;if s.user_id is null or not a.ascended then raise exception '尚未踏入仙界';end if;if s.guide_stone_stage<3 or not s.outer_route_cleared then raise exception '界軀尚未解鎖';end if;idx:=s.wasteland_body_stage+1;if idx not between 1 and 3 then raise exception '界軀已達目前上限';end if;if s.residual_source<source_cost[idx]or s.barren_traces<trace_cost[idx]then raise exception '淬鍊界軀所需材料不足';end if;update private.player_immortal_states set residual_source=residual_source-source_cost[idx],barren_traces=barren_traces-trace_cost[idx],wasteland_body_stage=idx,revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into s;insert into private.player_state_events(user_id,channel,revision,event_type,request_id,payload)values(uid,p_channel,s.revision,'immortal_body_upgraded',p_request_id,jsonb_build_object('stage',idx));return private.immortal_snapshot(s);end$$;
revoke all on function private.immortal_day(),private.immortal_snapshot(private.player_immortal_states)from public,anon,authenticated;revoke execute on function public.player_immortal_bootstrap(text,jsonb),public.player_immortal_wasteland_route(text,text,uuid),public.player_immortal_body_upgrade(text,uuid)from public,anon;grant execute on function public.player_immortal_bootstrap(text,jsonb),public.player_immortal_wasteland_route(text,text,uuid),public.player_immortal_body_upgrade(text,uuid)to authenticated;
